// MineBench entry: "a choo-choo train".
// A black steam loco with brass trim, coal tender, three wooden coaches on rails over
// a ballast embankment and a river bridge, a lit station platform with a brick station
// house, forest, snowcapped mountains and a smoke plume.

const TZ = 128;                                       // track centre line (z)
const RIV = 60;                                       // river centre line (x)
const YARD = { x0: 92, x1: 150, z0: 96, z1: 120 };    // flattened station yard

const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
const smooth = (a, b, v) => { const t = clamp((v - a) / (b - a), 0, 1); return t * t * (3 - 2 * t); };
const pick = (a, b) => a + Math.floor(rng() * (b - a + 1));   // inclusive random integer

// ---------- landscape ----------
function surfaceY(x, z) {
  const dz = Math.abs(z - TZ);
  let h = 7 + 4 * Math.sin(x * 0.061 + 1.3) + 3 * Math.sin(z * 0.093 + x * 0.021) + 1.5 * Math.sin((x + 2 * z) * 0.19);
  // distant mountains only at the far ends of the grid, so the train is never hidden behind a massif
  h += smooth(95, 125, dz) * (40 + 12 * Math.sin(x * 0.037 + z * 0.05) + 5 * Math.sin(x * 0.11));
  h = 5 + (h - 5) * smooth(9, 40, dz);                // flat meadow beside the track, so the train reads from any side
  if (x >= YARD.x0 && x <= YARD.x1 && z >= YARD.z0 && z <= YARD.z1) h = 13;
  return Math.max(3, Math.round(h));
}

function column(x, z) {
  const dx = Math.abs(x - RIV);
  if (dx <= 4) {                                      // river channel
    block(x, 0, z, 'sand'); block(x, 1, z, 'sand'); block(x, 2, z, 'water');
    return;
  }
  let s = surfaceY(x, z);
  if (dx <= 6) s = Math.min(s, 4);                    // sandy banks
  if (s >= 40) {                                      // rock, snowcapped high up
    box(x, 0, z, x, s - 1, z, 'stone');
    block(x, s, z, s >= 60 ? 'white_wool' : 'stone');
  } else {
    const lo = Math.max(0, s - 3);
    if (lo > 0) box(x, 0, z, x, lo - 1, z, 'stone');
    box(x, lo, z, x, s - 1, z, 'dirt');
    block(x, s, z, dx <= 6 ? 'sand' : 'grass_block');
  }
}

for (let x = 0; x < 256; x++) for (let z = 0; z < 256; z++) column(x, z);

// ---------- track: ballast, sleepers, rails, river bridge ----------
box(4, 5, 119, 251, 5, 137, 'cobblestone');
for (let x = 4; x <= 251; x += 2) box(x, 6, 122, x, 6, 134, 'oak_planks');
box(4, 7, 124, 251, 7, 124, 'iron_block');
box(4, 7, 132, 251, 7, 132, 'iron_block');
box(57, 0, 122, 58, 4, 134, 'stone_bricks');
box(62, 0, 122, 63, 4, 134, 'stone_bricks');

// ---------- station: platform, house, lamps, benches, people ----------
box(92, 0, 112, 150, 13, 120, 'stone_bricks');
box(92, 13, 120, 150, 13, 120, 'yellow_wool');
box(100, 13, 98, 140, 13, 111, 'stone_bricks');
box(100, 14, 98, 140, 24, 98, 'bricks');
box(100, 14, 99, 100, 24, 111, 'bricks');
box(140, 14, 99, 140, 24, 111, 'bricks');
box(100, 14, 111, 140, 24, 111, 'bricks');
for (let x = 102; x <= 138; x++) {
  if ((x - 100) % 6 === 0) continue;                  // brick mullions
  box(x, 17, 111, x, 21, 111, 'glass');
}
box(119, 14, 111, 120, 18, 111, 'brown_wool');        // door
for (let k = 0; k < 8; k++) box(97, 25 + k, 97 + k, 143, 25 + k, 112 - k, 'red_wool');
box(97, 32, 104, 143, 32, 105, 'gold_block');         // ridge cap
for (const bx of [104, 130]) box(bx, 14, 114, bx + 5, 14, 114, 'oak_planks');
for (let lx = 96; lx <= 146; lx += 12) {
  box(lx, 14, 118, lx, 17, 118, 'iron_block');
  block(lx, 18, 118, 'glowstone');
}
function person(x, z, shirt) {
  block(x, 14, z, 'blue_wool'); block(x, 15, z, 'blue_wool');
  block(x, 16, z, shirt); block(x, 17, z, shirt);
  block(x, 18, z, 'orange_wool');
}
person(100, 116, 'red_wool');
person(103, 112, 'blue_wool');
person(121, 116, 'green_wool');
person(126, 113, 'orange_wool');
person(137, 116, 'yellow_wool');
person(145, 113, 'red_wool');

// ---------- locomotive pieces ----------
function wheel(xc, zc) {                              // disc in the x-y plane, centred on a rail
  for (let x = xc - 4; x <= xc + 4; x++) {
    for (let y = 7; y <= 15; y++) {
      const d = Math.hypot(x - xc, y - 11);
      if (d > 3.5) continue;
      let m = 'red_wool';
      if (d <= 2.5) m = 'black_wool';
      if (d <= 2.5 && (Math.abs(x - xc) < 0.5 || Math.abs(y - 11) < 0.5)) m = 'iron_block';
      if (d < 0.5) m = 'gold_block';
      for (let z = zc - 1; z <= zc + 1; z++) block(x, y, z, m);
    }
  }
}

function coach(x0, x1) {
  const mid = Math.floor((x0 + x1) / 2);
  for (const xc of [x0 + 3, x1 - 3]) { wheel(xc, 124); wheel(xc, 132); }
  for (let x = x0; x <= x1; x++) {
    for (let y = 14; y <= 26; y++) {
      for (let z = 122; z <= 134; z++) {
        const dz = z - TZ;
        const outer = (y >= 14 && y <= 20 && Math.abs(dz) <= 6) || (y > 20 && (y - 20) * (y - 20) + dz * dz <= 36);
        if (!outer) continue;
        const inner = (y >= 15 && y <= 20 && Math.abs(dz) <= 5) || (y > 20 && (y - 20) * (y - 20) + dz * dz <= 25);
        const end = x === x0 || x === x1;
        if (!end && inner) continue;                  // hollow cabin
        let m = 'oak_planks';
        if (y === 14) m = 'black_wool';
        else if (y >= 21) m = 'red_wool';
        else if (Math.abs(dz) === 6 && y === 20) m = 'gold_block';
        else if (Math.abs(dz) === 6 && x === mid && y <= 19) m = 'brown_wool';
        else if (Math.abs(dz) === 6 && y >= 16 && y <= 18 && !end && ((x - x0) % 4 === 1 || (x - x0) % 4 === 2)) m = 'glass';
        block(x, y, z, m);
      }
    }
  }
  for (let x = x0 + 2; x <= x1 - 2; x += 3) {         // seats
    box(x, 15, 125, x + 1, 15, 125, 'red_wool');
    box(x, 15, 131, x + 1, 15, 131, 'red_wool');
  }
  for (let x = x0 + 2; x <= x1 - 2; x += 4) block(x, 21, 128, 'glowstone');
}

// ---------- engine: boiler, cab, smokebox, chimney, cowcatcher ----------
for (const xc of [180, 187, 194]) { wheel(xc, 124); wheel(xc, 132); }
box(180, 11, 122, 194, 11, 122, 'iron_block');        // side rods
box(180, 11, 134, 194, 11, 134, 'iron_block');
box(176, 14, 126, 198, 15, 130, 'iron_block');        // frame

for (let x = 176; x <= 198; x++) {                    // boiler: a cylinder along x
  for (let y = 15; y <= 25; y++) {
    for (let z = 123; z <= 133; z++) {
      const r = Math.hypot(y - 20, z - TZ);
      if (r > 5) continue;
      let m = 'black_wool';
      if (y - 20 >= 3 && r >= 3.8) m = 'gray_wool';   // sheen along the top
      if ((x === 178 || x === 194) && r >= 4) m = 'gold_block';
      if (x >= 197) m = 'iron_block';                 // smokebox
      block(x, y, z, m);
    }
  }
}
for (let y = 15; y <= 25; y++) {                      // smokebox door
  for (let z = 123; z <= 133; z++) {
    if (Math.hypot(y - 20, z - TZ) <= 4.5) block(199, y, z, 'iron_block');
  }
}
box(200, 19, 127, 201, 21, 129, 'glowstone');         // headlamp

for (let y = 8; y <= 12; y++) {                       // cowcatcher bars
  for (let z = 122; z <= 134; z += 2) {
    for (let x = 199; x <= 203 - (y - 8); x++) block(x, y, z, 'iron_block');
  }
}

box(175, 21, 123, 187, 25, 133, 'black_wool');        // cab deck
box(175, 26, 123, 187, 33, 123, 'black_wool');        // cab sides
box(175, 26, 133, 187, 33, 133, 'black_wool');
box(175, 26, 124, 175, 33, 132, 'black_wool');        // cab back
box(177, 27, 123, 184, 31, 123, 'glass');
box(177, 27, 133, 184, 31, 133, 'glass');
box(175, 27, 126, 175, 31, 130, 'glass');
box(174, 34, 122, 188, 34, 134, 'red_wool');          // cab roof
box(174, 15, 123, 175, 22, 133, 'black_wool');        // engine apron

box(189, 26, 126, 191, 26, 130, 'gold_block');        // steam dome
box(190, 27, 127, 190, 27, 129, 'gold_block');

box(193, 25, 126, 195, 30, 130, 'black_wool');        // chimney
box(192, 31, 125, 196, 31, 131, 'iron_block');        // flared top
box(193, 32, 126, 195, 32, 130, 'black_wool');

// ---------- tender and coaches ----------
box(158, 15, 123, 173, 22, 133, 'black_wool');
box(160, 23, 124, 171, 23, 132, 'cobblestone');       // coal
box(158, 18, 123, 173, 18, 123, 'gold_block');
box(158, 18, 133, 173, 18, 133, 'gold_block');
for (const xc of [160, 167]) { wheel(xc, 124); wheel(xc, 132); }

coach(137, 155);
coach(115, 133);
coach(93, 111);

box(156, 12, 127, 157, 13, 129, 'iron_block');         // couplers
box(134, 12, 127, 136, 13, 129, 'iron_block');
box(112, 12, 127, 114, 13, 129, 'iron_block');

// ---------- forest ----------
function tree(x, s, z, h) {
  for (let y = s + 1; y <= s + h; y++) block(x, y, z, 'oak_log');
  const cy = s + h + 1;
  const r = 2.6 + rng() * 1.2;
  for (let dx = -4; dx <= 4; dx++) {
    for (let dy = -3; dy <= 3; dy++) {
      for (let dz = -4; dz <= 4; dz++) {
        const d = dx * dx + dy * dy * 1.2 + dz * dz;
        if (d > r * r + rng() * 2 - 1) continue;
        if (dx === 0 && dz === 0 && dy <= 0) continue;   // keep the trunk visible
        block(x + dx, cy + dy, z + dz, 'oak_leaves');
      }
    }
  }
}
// telegraph poles along the far side of the track, with cross-arms
for (let x = 10; x <= 246; x += 16) {
  const s = surfaceY(x, 141);
  box(x, s + 1, 141, x, s + 9, 141, 'oak_planks');
  box(x - 2, s + 8, 141, x + 2, s + 8, 141, 'oak_planks');
}
// two signal posts at the station ends
for (const sx of [84, 158]) {
  box(sx, 6, 138, sx, 13, 138, 'iron_block');
  block(sx, 14, 138, 'red_wool'); block(sx, 15, 138, 'green_wool');
}

let trees = 0;
for (let i = 0; i < 1200 && trees < 90; i++) {
  const x = pick(6, 249), z = pick(6, 249);
  if (Math.abs(z - TZ) <= 13) continue;
  if (Math.abs(x - RIV) <= 9) continue;
  if (x >= 86 && x <= 156 && z <= 124) continue;
  const s = surfaceY(x, z);
  if (s < 6 || s >= 40) continue;
  tree(x, s, z, pick(4, 6));
  trees++;
}

// ---------- smoke plume trailing back from the chimney ----------
function puff(cx, cy, cz, r) {
  for (let x = Math.floor(cx - r); x <= Math.ceil(cx + r); x++) {
    for (let y = Math.floor(cy - r); y <= Math.ceil(cy + r); y++) {
      for (let z = Math.floor(cz - r); z <= Math.ceil(cz + r); z++) {
        const d = (x - cx) * (x - cx) + (y - cy) * (y - cy) + (z - cz) * (z - cz);
        if (d > r * r * (0.85 + rng() * 0.3)) continue;
        block(x, y, z, (y < cy - r * 0.3 && rng() < 0.5) ? 'gray_wool' : 'white_wool');
      }
    }
  }
}
for (let k = 0; k < 12; k++) puff(194 - 2.6 * k, 34 + 1.5 * k, 128 + 1.8 * Math.sin(k * 1.1), 2.1 + 0.42 * k);
